1	function [BASISdiff] = osp_addDiffMMPeaks(BASISdiff,BASISoff,fitOpts)
2	    n = BASISdiff.n;
3	    sw = BASISdiff.spectralwidth;
4	    Bo = BASISdiff.Bo;
5	    centerFreq = BASISdiff.centerFreq;
6	    % The amplitude and FWHM values are determined as for the LCModel and
7	    % TARQUIN algorithms (see Wilson et al., MRM 2011).
8	    hzppm = Bo*42.577;
9	
10	    % To scale the amplitudes correctly, we first need to determine the
11	    % area of the 3.027 ppm CH3 signal of creatine
12	    [CrArea] = detCrArea(BASISoff);
13	    oneProtonArea = CrArea/3;
14	    
15	    % Next, we determine the area of a Gaussian singlet with nominal area 1
16	    testGaussian    = op_gaussianPeak(n,sw,Bo,centerFreq,0.1*hzppm,0,1);
17	    testGaussian    = op_dccorr(testGaussian,'p');
18	    gaussianArea    = sum(real(testGaussian.specs));
19	    
20	     % Find the GABA basis function
21	    idx_GABA          = find(strcmp(BASISdiff.name,'GABA'));
22	    if isempty(idx_GABA)
23	        error('No basis function with nametag ''GABA'' found! Abort!');
24	    end
25	 
26	    if strcmp(fitOpts.coMM3, '1to1GABA') % 1:1 GABA and co-edited MM3 model
27	        MM3co  = op_gaussianPeak(n,sw,Bo,centerFreq,fitOpts.FWHMcoMM3,3,2*oneProtonArea/gaussianArea);
28	        MM3co  = op_dccorr(MM3co,'p');
29	        BASISdiff.fids(:,idx_GABA)  = BASISdiff.fids(:,idx_GABA) +  MM3co.fids;
30	        BASISdiff.specs(:,idx_GABA) = BASISdiff.specs(:,idx_GABA) +  MM3co.specs;
31	    end    
32	    
33	    if strcmp(fitOpts.coMM3, '3to2MM') % 3:2 MM09 and co-edited MM3 model
34	        idx_MM          = find(strcmp(BASISdiff.name,'MM09'));
35	        if isempty(idx_MM)
36	            error('No basis function with nametag ''MM09'' found! Abort!');
37	        end
38	        MM3co  = op_gaussianPeak(n,sw,Bo,centerFreq,fitOpts.FWHMcoMM3,3,2*oneProtonArea/gaussianArea);
39	        MM3co  = op_dccorr(MM3co,'p');
40	        BASISdiff.fids(:,idx_MM)  = BASISdiff.fids(:,idx_MM) +  MM3co.fids;
41	        BASISdiff.specs(:,idx_MM) = BASISdiff.specs(:,idx_MM) +  MM3co.specs;
42	    end   
43	    
44	    if strcmp(fitOpts.coMM3, '3to2MMsoft') % 3:2 MM09 and co-edited MM3 model
45	        idx_MM          = find(strcmp(BASISdiff.name,'MM09'));
46	        if isempty(idx_MM)
47	            error('No basis function with nametag ''MM09'' found! Abort!');
48	        end
49	        MM3co  = op_gaussianPeak(n,sw,Bo,centerFreq,fitOpts.FWHMcoMM3,3,2*oneProtonArea/gaussianArea);
50	        MM3co  = op_dccorr(MM3co,'p');
51	        BASISdiff.name{BASISdiff.nMets+BASISdiff.nMM+1}       = 'MM3co';
52	        BASISdiff.fids(:,BASISdiff.nMets+BASISdiff.nMM+1)   = MM3co.fids;
53	        BASISdiff.specs(:,BASISdiff.nMets+BASISdiff.nMM+1)  = MM3co.specs;    
54	        BASISdiff.nMM = BASISdiff.nMM + 1;
55	    end 
56	
57	    if strcmp(fitOpts.coMM3, 'freeGauss') || strcmp(fitOpts.coMM3, 'fixedGauss') || strcmp(fitOpts.coMM3, '1to1GABAsoft')...
58	        || strcmp(fitOpts.coMM3, '2to3GABAsoft') || strcmp(fitOpts.coMM3, '3to2GABAsoft')% free co-edited MM3 model and soft constraints model
59	        MM3co  = op_gaussianPeak(n,sw,Bo,centerFreq,fitOpts.FWHMcoMM3,3,2*oneProtonArea/gaussianArea);
60	        MM3co  = op_dccorr(MM3co,'p');
61	        BASISdiff.name{BASISdiff.nMets+BASISdiff.nMM+1}       = 'MM3co';
62	        BASISdiff.fids(:,BASISdiff.nMets+BASISdiff.nMM+1)   = MM3co.fids;
63	        BASISdiff.specs(:,BASISdiff.nMets+BASISdiff.nMM+1)  = MM3co.specs;    
64	        BASISdiff.nMM = BASISdiff.nMM + 1;
65	    end
66	    
67	    if strcmp(fitOpts.coMM3, 'freeGauss')
68	        BASISdiff.coMM3.MMArea = 2*oneProtonArea/gaussianArea;
69	        BASISdiff.coMM3.n = n;
70	        BASISdiff.coMM3.sw = sw;
71	        BASISdiff.coMM3.Bo = Bo;
72	        BASISdiff.coMM3.centerFreq = centerFreq;        
73	    end
74	    
