basis.n = double(checkpoint.points(1));
basis.name = task025_strings(checkpoint.component_names);
basis.names = task025_strings(checkpoint.subspectrum_names);
basis.nMets = double(checkpoint.n_metabolites(1));
basis.nMM = double(checkpoint.n_macromolecules(1));

container = struct();
