    ref_b = basis; ref_b.fids = basis.fids(:,:,1); ref_b.specs = basis.specs(:,:,1);
    d1_b  = basis; d1_b.fids  = basis.fids(:,:,3); d1_b.specs  = basis.specs(:,:,3);
else
